import{_ as t,c as i,o as a,ag as l}from"./chunks/framework.C86mscM5.js";const d=JSON.parse('{"title":"Helm、Kustomize 与 GitOps","description":"","frontmatter":{},"headers":[],"relativePath":"devops/orchestration/helm-kustomize-gitops.md","filePath":"devops/orchestration/helm-kustomize-gitops.md","lastUpdated":1788092044000}'),o={name:"devops/orchestration/helm-kustomize-gitops.md"};function s(r,e,n,m,h,u){return a(),i("div",null,e[0]||(e[0]=[l('<h1 id="helm、kustomize-与-gitops" tabindex="-1">Helm、Kustomize 与 GitOps <a class="header-anchor" href="#helm、kustomize-与-gitops" aria-label="Permalink to &quot;Helm、Kustomize 与 GitOps&quot;">​</a></h1><h2 id="工具定位" tabindex="-1">工具定位 <a class="header-anchor" href="#工具定位" aria-label="Permalink to &quot;工具定位&quot;">​</a></h2><ul><li><strong>Helm</strong>：使用 Chart、模板和 values 打包可复用应用。</li><li><strong>Kustomize</strong>：在原生 YAML 基础上通过 base/overlay 组合环境差异。</li><li><strong>GitOps</strong>：以 Git 中声明的期望状态为准，由控制器持续同步集群。</li></ul><p>Helm 与 Kustomize 可以组合使用，GitOps 也不限定模板工具。选择标准应是配置可读、差异可审查、渲染可验证，而不是模板能力越强越好。</p><h2 id="最小交付流程" tabindex="-1">最小交付流程 <a class="header-anchor" href="#最小交付流程" aria-label="Permalink to &quot;最小交付流程&quot;">​</a></h2><ol><li>CI 构建并推送不可变镜像。</li><li>更新部署仓库中的镜像 digest 或版本。</li><li>Pull Request 展示渲染后的清单差异并执行策略校验。</li><li>合并后由 Argo CD 等控制器同步目标环境。</li><li>控制器报告漂移和健康状态，告警系统判断用户影响。</li></ol><h2 id="生产注意事项" tabindex="-1">生产注意事项 <a class="header-anchor" href="#生产注意事项" aria-label="Permalink to &quot;生产注意事项&quot;">​</a></h2><ul><li>Secret 不以明文提交到 Git；使用 External Secrets、SOPS 等受控方案。</li><li>Chart 与应用版本分别管理，锁定依赖并测试升级与回滚。</li><li>限制 GitOps 控制器权限和可管理 Namespace。</li><li>紧急手工变更必须回写 Git，否则会被控制器覆盖或形成漂移。</li></ul>',8)]))}const c=t(o,[["render",s]]);export{d as __pageData,c as default};
